\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [834, 1589, 1109, 1725], \"page_id\": 3}], \"content\": \"The Treasury Bulletin is for sale by the Superintendent of Documents U.S. Government Printing Office Washington, D.C. 20402.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [204, 780, 1428, 971], \"page_id\": 4}], \"content\": \"The Treasury Bulletin is issued quarterly in March, June, September, and December by the Financial Management Service. The Budget Reports Division, Governmentwide Accounting, compiles statistical data from sources within Treasury departmental offices and bureaus, as well as various other Federal program agencies. Readers can contact the publication staff at (202) 874-9938/9939 to inquire about any of the published information. Suggestions are welcome.\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [415, 992, 1217, 1035], \"page_id\": 4}], \"content\": \"The publication staff can also be reached by electronic mail.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [561, 1077, 1069, 1117], \"page_id\": 4}], \"content\": \"treasury.bulletin@fms.treas.gov\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [204, 1157, 1428, 1223], \"page_id\": 4}], \"content\": \"Internet service subscribers can access the Treasury Bulletin in Microsoft Word or PDF format through the Financial Management Service's home page.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [667, 1268, 964, 1308], \"page_id\": 4}], \"content\": \"www.fms.treas.gov/\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [681, 193, 934, 264], \"page_id\": 5}], \"content\": \"Contents\", \"description\": null, \"id\": 0, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [144, 323, 543, 358], \"page_id\": 5}], \"content\": \"FINANCIAL OPERATIONS\", \"description\": nu