rently\n# Search for any element with bbox (bounding box) that might contain chart data\nelements = data.get('document', {}).get('elements', [])\n\n# Look for any element that has content with numbers and years\nfor i, elem in enumerate(elements):\n    if isinstance(elem, dict):\n        content = json.dumps(elem)\n        # Check if element has numeric data near employment\n        if 'employment' in content.lower() or 'payroll' in content.lower():\n            if '2004' in content or '2005' in content or '2006' in content:\n                print(f\"Element {i}: {content[:200]}\")\n                print()\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
